import sys
import subprocess

def generate_and_install(deps):
    with open('requirements.txt', 'w') as f:
        for dep in deps:
            f.write(f'{dep}\n')
    subprocess.run(['pip', 'install', '-r', 'requirements.txt'])

if __name__ == '__main__':
    generate_and_install(sys.argv[1:])

