import subprocess
import json

def generate_locked_requirements(input_file, output_file):
    print('Compiling locked requirements...')
    subprocess.run(['pip-compile', input_file, '--output-file', output_file], check=True)
    print(f'Locked requirements written to {output_file}')

def detect_mismatch(locked_file):
    result = subprocess.run(['pip', 'freeze'], capture_output=True, text=True, check=True)
    installed = {line.split('==')[0] for line in result.stdout.splitlines()}
    with open(locked_file, 'r') as f:
        locked = {line.split('==')[0] for line in f if line.strip() and not line.startswith('#')}
    missing = locked - installed
    extra = installed - locked
    if missing or extra:
        print('Mismatch detected:')
        if missing:
            print(f'  Missing: {sorted(missing)}')
        if extra:
            print(f'  Extra: {sorted(extra)}')
        print('Suggestion: run pip-compile to regenerate requirements.txt')
    else:
        print('All packages match the locked file.')

if __name__ == '__main__':
    generate_locked_requirements('requirements.in', 'requirements.txt')
    detect_mismatch('requirements.txt')
